// Service Worker for Push Notifications
// This SW handles push notifications while Workbox handles caching

import { precacheAndRoute } from 'workbox-precaching';

// Precache assets generated by Vite PWA
precacheAndRoute(self.__WB_MANIFEST || []);

 
// Push notification handler
self.addEventListener('push', (event) => {
 
  if (!event.data) {
     return;
  }

  let data;
  try {
    data = event.data.json();
   } catch (error) {
    console.error('[SW] Error parsing push data:', error);
    return;
  }

  const title = data.title || 'So-mails';
  const options = {
    body: data.body || 'New notification',
    icon: data.icon || '/logo.png',
    badge: '/logo.png',
    tag: data.tag || 'so-mails-notification',
    renotify: true,
    data: data.data || {},
    requireInteraction: false,
    vibrate: [200, 100, 200]
  };

  event.waitUntil(
    self.registration.showNotification(title, options)
      .then(() => {
       })
      .catch((error) => {
        console.error('[SW] showNotification FAILED:', error);
      })
  );
});

// Notification click handler
self.addEventListener('notificationclick', (event) => {
 
  event.notification.close();

  const urlToOpen = event.notification.data?.url || '/dashboard';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        if (client.url.includes(urlToOpen) && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});

// Handle push subscription changes
self.addEventListener('pushsubscriptionchange', (event) => {
 
  event.waitUntil(
    self.registration.pushManager.subscribe(event.oldSubscription.options)
      .then((subscription) => {
         return fetch('/user/push-subscription', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ subscription: subscription.toJSON() }),
          credentials: 'include',
        });
      })
      .catch((error) => {
        console.error('[SW] Resubscribe failed:', error);
      })
  );
});